#include <PID_v1.h>
double input, output, sp = {{setpoint}};
PID pid(&input, &output, &sp, {{kp}}, {{ki}}, {{kd}}, DIRECT);
void setup() {
    pinMode({{heater_pin}}, OUTPUT);
    pid.SetMode(AUTOMATIC);
    pid.SetOutputLimits(0, 255);
}
void loop() {
    input = read_temp();
    pid.Compute();
    analogWrite({{heater_pin}}, (int)output);
}
